#!/usr/bin/env python3
"""Cross-compile the swh LADSPA plugins (generated by makestub.pl) for Android arm64 -> libladspa_<name>.so"""
import os, re, subprocess, sys, glob
R = os.path.expanduser('~/kdenlive-android')
SWH = R + '/src/ladspa-src/swh'
OUT = R + '/build/ladspa-libs'
CC = R + '/sdk/ndk/30.0.14904198/toolchains/llvm/prebuilt/linux-x86_64/bin/aarch64-linux-android28-clang'
os.makedirs(OUT, exist_ok=True)
# minimal config.h the generated code expects
cfg = R + '/build/ladspa-swh-config'
os.makedirs(cfg, exist_ok=True)
open(cfg + '/config.h', 'w').write('#define HAVE_FFTW3 1\n#define FFTW3 1\n#define VERSION "0.4.17"\n')

# plugin -> extra libs, from Makefile.am
extra = {}
mk = open(SWH + '/Makefile.am').read().replace('\\\n', ' ')
for m in re.finditer(r'^(\w+)_la_LIBADD\s*=\s*(.*)$', mk, re.M):
    extra[m.group(1)] = m.group(2).split()
srcs = {'-lblo': ['util/blo.c'], '-ldb': ['util/db.c'], '-lrms': ['util/rms.c'], '-liir': ['util/iir.c'],
        '-lpitchscale': ['util/pitchscale.c'], 'gsm/libgsm.a': [f for f in glob.glob(SWH + '/gsm/*.c')],
        '-lgverb': [f for f in glob.glob(SWH + '/gverb/*.c') if 'test' not in f]}
fftwf = os.path.exists(R + '/CraftRoot/lib/libfftw3f_arm64-v8a.so')
only = sys.argv[1:]
ok, fail, skipped = [], [], []
for c in sorted(glob.glob(SWH + '/gen/*.c')):
    name = os.path.basename(c)[:-2]
    if only and name not in only:
        continue
    libs = extra.get(name, [])
    needs_fftw = any('FFTW' in l for l in libs) or '-lpitchscale' in libs
    if needs_fftw and not fftwf:
        skipped.append(name)
        continue
    files = [c]
    ldx = []
    for l in libs:
        if l in srcs:
            files += [(f if os.path.isabs(f) else SWH + '/' + f) for f in srcs[l]]
    if needs_fftw:
        ldx = [R + '/CraftRoot/lib/libfftw3f_arm64-v8a.so']
    cmd = [CC, '-O3', '-fPIC', '-DPIC', '-ffast-math', '-fomit-frame-pointer', '-Wno-everything',
           '-I' + cfg, '-I' + SWH, '-I' + SWH + '/util', '-I' + SWH + '/gverb', '-I' + SWH + '/gsm',
           '-I' + R + '/CraftRoot/include', '-DHAVE_CONFIG_H', '-shared', '-Wl,-Bsymbolic'] + files + ldx + \
          ['-lm', '-o', OUT + '/libladspa_' + name + '.so']
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode == 0:
        ok.append(name)
    else:
        fail.append(name)
        print('FAIL', name, r.stderr.strip().splitlines()[:3])
print('swh: ok=%d fail=%d skipped(no fftw3f)=%d' % (len(ok), len(fail), len(skipped)), skipped)
